-- Cloud category vocabulary. The checked-in profile JSON is the seed and export format.
CREATE TABLE energy_category_groups (
  key text PRIMARY KEY CHECK (key ~ '^[a-z0-9][a-z0-9_]*$'),
  label text NOT NULL CHECK (length(btrim(label)) > 0),
  sort_order integer NOT NULL
);
CREATE TABLE energy_categories (
  key text PRIMARY KEY CHECK (key ~ '^[a-z0-9][a-z0-9_]*$'),
  label text NOT NULL CHECK (length(btrim(label)) > 0),
  group_key text NOT NULL REFERENCES energy_category_groups(key),
  sort_order integer NOT NULL,
  usage_kind text NOT NULL CHECK (usage_kind IN ('hours_per_week','cycles_per_week','always_on')),
  default_usage numeric CHECK (default_usage >= 0),
  standby_applies boolean NOT NULL,
  typical_active_watts numeric CHECK (typical_active_watts >= 0),
  typical_standby_watts numeric CHECK (typical_standby_watts >= 0),
  typical_kwh_per_cycle numeric CHECK (typical_kwh_per_cycle >= 0),
  typical_cycle_hours numeric CHECK (typical_cycle_hours >= 0),
  demo_active_watts numeric NOT NULL CHECK (demo_active_watts > 0),
  demo_hours_per_day numeric NOT NULL CHECK (demo_hours_per_day > 0),
  profile jsonb NOT NULL CHECK (jsonb_typeof(profile) = 'object'),
  origin text NOT NULL CHECK (origin IN ('seed','discovered')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX energy_categories_group_idx ON energy_categories(group_key, sort_order, key);
CREATE TABLE energy_category_aliases (
  alias text PRIMARY KEY CHECK (alias ~ '^[a-z0-9][a-z0-9_]*$'),
  category_key text NOT NULL REFERENCES energy_categories(key),
  origin text NOT NULL CHECK (origin IN ('seed','discovered')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE energy_category_catalog (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  version bigint NOT NULL CHECK (version > 0),
  meta jsonb NOT NULL CHECK (jsonb_typeof(meta) = 'object')
);

