INSERT INTO energy_categories(key,label,group_key,sort_order,usage_kind,default_usage,standby_applies,typical_active_watts,typical_standby_watts,typical_kwh_per_cycle,typical_cycle_hours,demo_active_watts,demo_hours_per_day,profile,origin) VALUES ('dishwasher','Dishwasher','dishwashing_laundry',10,'cycles_per_week',3.5,true,500,0.5,1,2,10,8,'{"slider":{"min":0,"max":14,"step":0.5,"default":3.5},"rating_basis":"cycles_per_year:184","plausibility":{"active_watts":[100,2500],"standby_watts":[0,10],"kwh_per_cycle":[0.3,3],"annual_kwh":[50,600]},"confidence":"estimate","source_ids":["doe_energy_saver_wattages","doe_tp_dishwasher_c2"],"notes":"Sourced: default 3.5/week ~ 184 cycles/yr / 52 (Appendix C2; ratings made under C1 used 215). Estimate: 500 W is the average over a 2 h cycle (DOE''s 1200-2400 W is the heater''s peak, which runs for only part of the cycle), 1 kWh/cycle, 0.5 W standby. Deliberately kept at DOE''s current 184 (not ENERGY STAR''s 215, decision 2026-09-23): ENERGY STAR ratings carry their own basis (kernel-kb energy_enrich writes rating_usage_basis cycles_per_year:215), so this value is only the fallback for an annual kWh with no basis of its own, e.g. a manual/spec-sheet figure."}','seed');
INSERT INTO energy_categories(key,label,group_key,sort_order,usage_kind,default_usage,standby_applies,typical_active_watts,typical_standby_watts,typical_kwh_per_cycle,typical_cycle_hours,demo_active_watts,demo_hours_per_day,profile,origin) VALUES ('washer','Washer','dishwashing_laundry',20,'cycles_per_week',4.5,true,400,1,0.4,1,10,8,'{"slider":{"min":0,"max":21,"step":0.5,"default":4.5},"rating_basis":"cycles_per_year:234","plausibility":{"active_watts":[100,1500],"standby_watts":[0,10],"kwh_per_cycle":[0.05,5],"annual_kwh":[20,1000]},"confidence":"estimate","source_ids":["doe_energy_saver_wattages","doe_tp_clothes_washer_2022"],"notes":"Sourced: 400 W within DOE''s 350-500 W; default 4.5/week = 234 cycles/yr / 52 (DOE 2022 test procedure). Estimate: 1 h cycle and 1 W standby. Machine electricity only; ENERGY STAR annual kWh may also include water-heating energy, so a KB rating_usage_basis always overrides this basis. Deliberately kept at DOE''s current 234 (not ENERGY STAR''s 295, decision 2026-09-23): ENERGY STAR ratings carry their own basis (kernel-kb energy_enrich writes rating_usage_basis cycles_per_year:295), so this value is only the fallback for an annual kWh with no basis of its own, e.g. a manual/spec-sheet figure, which follows the current DOE procedure. Dividing a 295-basis figure by 234 would overstate per-cycle kWh by ~26%."}','seed');
INSERT INTO energy_categories(key,label,group_key,sort_order,usage_kind,default_usage,standby_applies,typical_active_watts,typical_standby_watts,typical_kwh_per_cycle,typical_cycle_hours,demo_active_watts,demo_hours_per_day,profile,origin) VALUES ('dryer','Dryer','dishwashing_laundry',30,'cycles_per_week',5.5,true,3000,1,3,1,10,8,'{"slider":{"min":0,"max":21,"step":0.5,"default":5.5},"rating_basis":"cycles_per_year:283","plausibility":{"active_watts":[300,6000],"standby_watts":[0,10],"kwh_per_cycle":[0.5,7],"annual_kwh":[100,2000]},"confidence":"estimate","source_ids":["doe_energy_saver_wattages","doe_tp_clothes_dryer_d2","doe_tp_clothes_dryer_2021"],"notes":"Sourced: 3000 W within DOE''s 1800-5000 W (electric); default 5.5/week ~ 283 cycles/yr / 52 (Appendix D1 / pre-2021 D2). Estimate: 1 h cycle, 1 W standby. Gas dryers use far less electricity; heat-pump dryers draw less power over longer cycles. Dated note 2026-09-24: rating_basis stays cycles_per_year:283, the basis of ratings made before 2028-03-01; ratings made under the amended Appendix D2 (mandatory from 2028-03-01, doe_tp_clothes_dryer_2021) use 236 cycles/yr and should carry rating_usage_basis cycles_per_year:236 on the KB row, which overrides this fallback."}','seed');
