INSERT INTO energy_category_catalog(id,version,meta) VALUES (true,1,'{"seed_version":"1.2.0","updated":"2026-09-28","fallback_category":"other","units":{"watts":"W, electrical input power","kwh_per_cycle":"kWh of electricity per cycle","cycle_hours":"hours per cycle","annual_kwh":"kWh per year","slider":"hours/week for hours_per_week, cycles/week for cycles_per_week"},"sources":[{"id":"doe_energy_saver_wattages","title":"U.S. DOE Energy Saver, ''Estimating Appliance and Home Electronic Energy Use'' (typical wattages list)","url":"https://www.energy.gov/energysaver/estimating-appliance-and-home-electronic-energy-use","notes":"Verified 2026-09-23 (search excerpt): clothes washer 350-500 W, clothes dryer 1800-5000 W, dishwasher 1200-2400 W. The same list''s other figures were not re-verified 2026-09-23; rows citing them for anything else are marked estimate."},{"id":"energystar_tv_tec","title":"ENERGY STAR Televisions key product criteria: typical energy consumption (TEC) model","url":"https://www.energystar.gov/products/televisions/key_product_criteria","notes":"TEC assumes 5 h/day On mode + 19 h/day Sleep mode. Certified TVs: Sleep mode <= 0.5 W (earlier spec versions allowed <= 1.0 W)."},{"id":"doe_tp_clothes_washer_2022","title":"DOE test procedures for residential clothes washers, final rule (87 FR, 2022-06-01, doc 2022-10715)","url":"https://www.federalregister.gov/documents/2022/06/01/2022-10715/energy-conservation-program-test-procedures-for-residential-and-commercial-clothes-washers","notes":"Representative annual use reduced from 295 cycles/yr (Appendix J2) to 234 cycles/yr. Older ENERGY STAR washer ratings used 295."},{"id":"doe_tp_clothes_dryer_d2","title":"DOE test procedure for consumer clothes dryers, 10 CFR 430 Subpart B Appendix D2","url":"https://www.ecfr.gov/current/title-10/chapter-II/subchapter-D/part-430/subpart-B/appendix-Appendix%20D2%20to%20Subpart%20B%20of%20Part%20430","notes":"Representative average use of 283 drying cycles/yr (2005 RECS) in Appendix D1 and in Appendix D2 before its 2021 amendment; see doe_tp_clothes_dryer_2021 for the amended 236 cycles/yr."},{"id":"doe_tp_clothes_dryer_2021","title":"DOE test procedure for clothes dryers, final rule (86 FR, 2021-10-08, doc 2021-21810) and energy conservation standards direct final rule (89 FR, 2024-03-12, doc 2024-04766)","url":"https://www.govinfo.gov/content/pkg/FR-2021-10-08/html/2021-21810.htm","notes":"Verified 2026-09-24. The 2021 rule ''updates the estimate to 236 clothes dryer cycles per year in appendix D2, based on the latest available 2015 survey data''; ''use of the amended value in appendix D2 is not required until'' DOE amends the standards. The 2024 direct final rule''s amended standards (CEF_D2) apply from 2028-03-01, when manufacturers ''will be required to use appendix D2''. So ratings made from 2028-03-01 use 236 cycles/yr; ratings made before then (Appendix D1, or pre-amendment D2) use 283."},{"id":"doe_tp_dishwasher_c2","title":"DOE test procedure for dishwashers, final rule (86 FR, 2021-12-22, doc 2021-26880), Appendix C2","url":"https://www.federalregister.gov/documents/2021/12/22/2021-26880/energy-conservation-program-test-procedure-for-dishwashers","notes":"Appendix C2 uses 184 cycles/yr; the older Appendix C1 (and ratings made under it) used 215."},{"id":"nrdc_small_network_equipment","title":"NRDC / Ecova, ''Small Network Equipment Energy Consumption in U.S. Homes'' (2013)","url":"https://www.nrdc.org/sites/default/files/residential-network-IP.pdf","notes":"Home routers average about 6 W (range about 2-20 W); measured 60 models in homes and lab."},{"id":"lbnl_whole_house_standby","title":"LBNL-45967, ''Whole-House Measurements of Standby Power Consumption''","url":"https://eta-publications.lbl.gov/sites/default/files/lbnl-45967.pdf","notes":"Per-appliance standby loads of 0.3-24 W; TVs, set-top boxes and printers among the largest standby loads. Used for standby plausibility bands and as the basis for standby estimates."},{"id":"lbnl_set_top_boxes","title":"LBNL-45305, ''Energy Use of Set-Top Boxes and Telephony Products in the U.S.''","url":"https://www.osti.gov/servlets/purl/785229","notes":"Cable/satellite set-top boxes draw about 10-25 W when ''off'', about the same as on. Used only for the media_player standby plausibility band (small streaming players draw far less)."}]}'::jsonb);
-- END GENERATED SEED

CREATE FUNCTION energy_category_version_bump() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE energy_category_catalog SET version = version + 1 WHERE id;
  RETURN NULL;
END $$;
CREATE TRIGGER energy_category_groups_version AFTER INSERT OR UPDATE OR DELETE ON energy_category_groups
  FOR EACH STATEMENT EXECUTE FUNCTION energy_category_version_bump();
CREATE TRIGGER energy_categories_version AFTER INSERT OR UPDATE OR DELETE ON energy_categories
  FOR EACH STATEMENT EXECUTE FUNCTION energy_category_version_bump();
CREATE TRIGGER energy_category_aliases_version AFTER INSERT OR UPDATE OR DELETE ON energy_category_aliases
  FOR EACH STATEMENT EXECUTE FUNCTION energy_category_version_bump();

CREATE FUNCTION energy_category_slug(input text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT COALESCE(NULLIF(btrim(regexp_replace(lower(btrim(COALESCE(input,''))),
         '[^a-z0-9]+', '_', 'g'), '_'), ''), 'other')
$$;

CREATE FUNCTION energy_category_ensure(input text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  k text := energy_category_slug(input);
  target text;
  cand text;
BEGIN
  PERFORM 1 FROM energy_categories WHERE key = k;
  IF FOUND THEN RETURN k; END IF;
  SELECT category_key INTO target FROM energy_category_aliases WHERE alias = k;
  IF target IS NOT NULL THEN RETURN target; END IF;
  FOREACH cand IN ARRAY ARRAY[regexp_replace(k, 'es$', ''), regexp_replace(k, 's$', '')] LOOP
    CONTINUE WHEN cand = k OR cand = '';
    SELECT key INTO target FROM energy_categories WHERE key = cand;
    IF target IS NULL THEN
      SELECT category_key INTO target FROM energy_category_aliases WHERE alias = cand;
    END IF;
    EXIT WHEN target IS NOT NULL;
  END LOOP;
  IF target IS NULL THEN
    SELECT key INTO target FROM energy_categories
     WHERE energy_category_slug(label) = k ORDER BY sort_order, key LIMIT 1;
  END IF;
  IF target IS NOT NULL THEN
    INSERT INTO energy_category_aliases(alias, category_key, origin)
    VALUES (k, target, 'discovered') ON CONFLICT (alias) DO NOTHING;
    SELECT category_key INTO target FROM energy_category_aliases WHERE alias = k;
    RETURN target;
  END IF;
  INSERT INTO energy_categories(key, label, group_key, sort_order, usage_kind, default_usage,
      standby_applies, demo_active_watts, demo_hours_per_day, profile, origin)
  SELECT k, left(btrim(input), 120), 'other',
         (SELECT COALESCE(max(sort_order), 0) + 10 FROM energy_categories WHERE group_key = 'other'),
         o.usage_kind, o.default_usage, o.standby_applies, 2, 8, o.profile - 'notes', 'discovered'
    FROM energy_categories o WHERE o.key = 'other'
  ON CONFLICT (key) DO NOTHING;
  RETURN k;
END $$;
